def _split_fields(text):
    """Split text on SEP, respecting quoted sections and doubled quotes."""
    fields = []
    current = []
    quoted = False
    index = 0
    while index < len(text):
        char = text[index]
        if char == QUOTE:
            if quoted and index + 1 < len(text) and text[index + 1] == QUOTE:
                current.append(QUOTE)
                current.append(QUOTE)
                index += 2
                continue
            quoted = not quoted
            current.append(char)
        elif char == SEP and not quoted:
            fields.append("".join(current))
            current = []
        else:
            current.append(char)
        index += 1
    if quoted:
        raise ValueError("unclosed quote")
    fields.append("".join(current))
    return fields


def _parse_value(raw):
    """Return the value of a field, unquoting it when it is quoted."""
    value = raw.strip()
    if not value.startswith(QUOTE):
        return value

    out = []
    index = 1
    while index < len(value):
        char = value[index]
        if char == QUOTE:
            if index + 1 < len(value) and value[index + 1] == QUOTE:
                out.append(QUOTE)
                index += 2
                continue
            index += 1
            break
        out.append(char)
        index += 1
    else:
        raise ValueError("unclosed quote")
    if value[index:].strip():
        raise ValueError(f"trailing text after quoted value: {value!r}")
    return "".join(out)


